CREATE TABLE "image_packs" (
  "id" serial PRIMARY KEY NOT NULL,
  "uuid" text NOT NULL,
  "organization_id" integer REFERENCES "organizations"("id") ON DELETE CASCADE,
  "is_system" boolean DEFAULT false NOT NULL,
  "slug" text NOT NULL,
  "name" text NOT NULL,
  "description" text,
  "created_at" integer DEFAULT extract(epoch from now())::int NOT NULL,
  "updated_at" integer DEFAULT extract(epoch from now())::int NOT NULL
);
--> statement-breakpoint
CREATE TABLE "image_pack_items" (
  "id" serial PRIMARY KEY NOT NULL,
  "uuid" text NOT NULL,
  "pack_id" integer NOT NULL REFERENCES "image_packs"("id") ON DELETE CASCADE,
  "slug" text NOT NULL,
  "name" text NOT NULL,
  "archimate_type" text,
  "storage_kind" text NOT NULL,
  "svg_content" text,
  "blob_url" text,
  "blob_pathname" text,
  "mime_type" text,
  "created_at" integer DEFAULT extract(epoch from now())::int NOT NULL
);
--> statement-breakpoint
